def attempts_until_success(fail_count, times):
    state = {"calls": 0}

    @retry(times=times)
    def flaky():
        state["calls"] += 1
        if state["calls"] <= fail_count:
            raise ValueError("not yet")
        return "ok"

    flaky()
    return state["calls"]

