def backoff_delays(fail_count, base_delay):
    delays = []

    @retry_with_backoff(times=fail_count + 1, base_delay=base_delay, sleep_fn=delays.append)
    def flaky():
        if len(delays) < fail_count:
            raise ValueError("not yet")
        return "ok"

    flaky()
    return delays

